11	// Heartbeat is one telemetry record reported by a node.
12	//
13	// JSON input uses snake_case field names:
14	//
15	//	node          string   node id (required, non-empty)
16	//	seq           integer  sequence number (required, > 0)
17	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00 (required)
18	//	version       string   version (required, non-empty)
19	//	height        integer  block height (required, >= 0)
20	//	missed        integer  cumulative missed duties (required, >= 0)
21	type Heartbeat struct {
22		NodeID      string    `json:"node"`
23		Seq         int64     `json:"seq"`
24		CollectedAt time.Time `json:"collected_at"`
25		Version     string    `json:"version"`
26		Height      int64     `json:"height"`
27		Missed      int64     `json:"missed"`
28	}
29	
30	// heartbeatFields enumerates every field that must be explicitly provided.
31	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
32	
33	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
34	// the moment the platform received the batch; a collection time later than
35	// receive time is rejected.
36	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
37		if h.NodeID == "" {
38			return fmt.Errorf("node id is empty")
39		}
40		if !utf8.ValidString(h.NodeID) {
41			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
42		}
43		if h.Seq <= 0 {
44			return fmt.Errorf("seq must be a positive integer, got %d", h.Seq)
45		}
46		if h.Version == "" {
47			return fmt.Errorf("version is empty")
48		}
49		if h.Height < 0 {
50			return fmt.Errorf("height must be >= 0, got %d", h.Height)
51		}
52		if h.Missed < 0 {
53			return fmt.Errorf("missed must be >= 0, got %d", h.Missed)
54		}
55		if h.CollectedAt.IsZero() {
56			return fmt.Errorf("collected_at is missing or invalid")
57		}
58		if h.CollectedAt.After(receiveTime) {
59			return fmt.Errorf("collected_at %s is later than receive time %s",
60				h.CollectedAt.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
61		}
62		return nil
63	}
64	
65	// Equal reports whether two records are the same telemetry. Collection times
66	// are compared as instants, so the same moment expressed in different
67	// timezones compares equal.
68	func (h Heartbeat) Equal(o Heartbeat) bool {
69		return h.NodeID == o.NodeID &&
70			h.Seq == o.Seq &&
71			h.Version == o.Version &&
72			h.Height == o.Height &&
73			h.Missed == o.Missed &&
74			h.CollectedAt.Equal(o.CollectedAt)
75	}
76	
77	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
78	// be explicitly provided; missing or unknown fields are rejected with a
79	// specific reason.
80	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
81		var raw []json.RawMessage
82		if err := json.Unmarshal(data, &raw); err != nil {
83			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
84		}
85		if len(raw) == 0 {
86			return nil, fmt.Errorf("no heartbeat records provided")
87		}
88		records := make([]Heartbeat, 0, len(raw))
89		for i, r := range raw {
90			h, err := parseOneHeartbeat(r, receiveTime)
91			if err != nil {
92				return nil, fmt.Errorf("record %d: %w", i+1, err)
93			}
94			records = append(records, h)
95		}
96		return records, nil
97	}
98	
99	// rejectNull reports an error when a required field's JSON value is null.
100	// A null value means the node did not report the field, which must not be
101	// silently saved as the zero value.
102	func rejectNull(raw json.RawMessage, field string) error {
103		if bytes.Equal(raw, []byte("null")) {
104			return fmt.Errorf("%s must not be null", field)
105		}
106		return nil
107	}
108	
109	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
110	// Heartbeat while enforcing the field rules at every trust boundary: all
111	// fields must be present and non-null, unknown fields are rejected, and a
112	// field may never appear twice in the same object — even with the same
113	// value, and even when one spelling uses a JSON Unicode escape denoting the
114	// same key. A plain struct/map unmarshal would instead keep the last
115	// occurrence and let an absent field masquerade as the zero value. Both the
116	// submit input path and the stored-file read path must use it.
117	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
118		// Walk the object with a streaming decoder so duplicate field names are
119		// detected. Field names are compared as the JSON string they represent:
120		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
121		// would silently keep only the last occurrence.
122		dec := json.NewDecoder(bytes.NewReader(raw))
123		tok, err := dec.Token()
124		if err != nil {
125			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
126		}
127		if d, ok := tok.(json.Delim); !ok || d != '{' {
128			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
129		}
130	
131		fields := make(map[string]json.RawMessage)
132		for dec.More() {
133			keyTok, err := dec.Token()
134			if err != nil {
135				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
136			}
137			key, ok := keyTok.(string)
138			if !ok {
139				return Heartbeat{}, fmt.Errorf("field name must be a string")
140			}
141			if _, exists := fields[key]; exists {
142				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
143			}
144			var val json.RawMessage
145			if err := dec.Decode(&val); err != nil {
146				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
147			}
148			fields[key] = val
149		}
150		// Consume the closing brace.
151		if _, err := dec.Token(); err != nil {
152			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
153		}
154	
155		for _, f := range heartbeatFields {
156			if _, ok := fields[f]; !ok {
157				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
158			}
159		}
160		for k := range fields {
161			if !containsString(heartbeatFields, k) {
162				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
163			}
164		}
165	
166		var h Heartbeat
167	
168		if err := rejectNull(fields["node"], "node"); err != nil {
169			return Heartbeat{}, err
170		}
171		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
172			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
173		}
174		if err := validateRawNodeText(fields["node"]); err != nil {
175			return Heartbeat{}, err
176		}
177		if h.NodeID == "" {
178			return Heartbeat{}, fmt.Errorf("node must not be empty")
179		}
180	
181		if err := rejectNull(fields["seq"], "seq"); err != nil {
182			return Heartbeat{}, err
183		}
184		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
185			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
186		}
187		if h.Seq <= 0 {
188			return Heartbeat{}, fmt.Errorf("seq must be a positive integer, got %d", h.Seq)
189		}
190	
191		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
192			return Heartbeat{}, err
193		}
194		var collectedStr string
195		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
196			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
197		}
198		t, err := time.Parse(time.RFC3339, collectedStr)
199		if err != nil {
200			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
201		}
202		h.CollectedAt = t
203	
204		if err := rejectNull(fields["version"], "version"); err != nil {
205			return Heartbeat{}, err
206		}
207		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
208			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
209		}
210		if h.Version == "" {
211			return Heartbeat{}, fmt.Errorf("version must not be empty")
212		}
213	
214		if err := rejectNull(fields["height"], "height"); err != nil {
215			return Heartbeat{}, err
216		}
217		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
218			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
219		}
220		if h.Height < 0 {
221			return Heartbeat{}, fmt.Errorf("height must be >= 0, got %d", h.Height)
222		}
223	
224		if err := rejectNull(fields["missed"], "missed"); err != nil {
225			return Heartbeat{}, err
226		}
227		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
228			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
229		}
230		if h.Missed < 0 {
231			return Heartbeat{}, fmt.Errorf("missed must be >= 0, got %d", h.Missed)
232		}
233	
234		return h, nil
235	}
236	
237	// validateRawNodeText checks the raw JSON string token of the node field
238	// before its decoded value is trusted. encoding/json silently rewrites
239	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
240	// would merge distinct node ids into one replacement-char id and break the
241	// ownership check against stored files. The raw token must decode
242	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
243	// escape must be a valid scalar value or a properly paired high/low
244	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
245	// user typed and is accepted; only undecodable input is rejected.
246	func validateRawNodeText(raw json.RawMessage) error {
247		raw = bytes.TrimSpace(raw)
248		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
249			return fmt.Errorf("node must be a string")
250		}
251		s := raw[1 : len(raw)-1]
252		for i := 0; i < len(s); {
253			c := s[i]
254			if c == '\\' {
255				if i+1 >= len(s) {
256					return fmt.Errorf("node contains a truncated escape")
257				}
258				if s[i+1] != 'u' {
259					i += 2
260					continue
261				}
262				if i+6 > len(s) {
263					return fmt.Errorf("node contains a truncated \\u escape")
264				}
265				r, err := parseHex4(s[i+2 : i+6])
266				if err != nil {
267					return fmt.Errorf("node contains an invalid \\u escape: %w", err)
268				}
269				switch {
270				case r >= 0xD800 && r <= 0xDBFF:
271					// A high surrogate is only valid when immediately followed
272					// by a low-surrogate \u escape.
273					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
274						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
275					}
276					lo, err := parseHex4(s[i+8 : i+12])
277					if err != nil {
278						return fmt.Errorf("node contains an invalid \\u escape: %w", err)
279					}
280					if lo < 0xDC00 || lo > 0xDFFF {
281						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
282					}
283					i += 12
284				case r >= 0xDC00 && r <= 0xDFFF:
285					return fmt.Errorf("node contains an unpaired low surrogate \\u%04X", r)
286				default:
287					i += 6
288				}
289				continue
290			}
291			if c < utf8.RuneSelf {
292				i++
293				continue
294			}
295			// A valid multi-byte rune decodes with size >= 2; size 1 means the
296			// bytes are not valid UTF-8 (including surrogate encodings).
297			_, size := utf8.DecodeRune(s[i:])
298			if size == 1 {
299				return fmt.Errorf("node contains invalid UTF-8 at byte offset %d", i)
300			}
301			i += size
302		}
303		return nil
304	}
305	
306	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
307	func parseHex4(b []byte) (rune, error) {
308		v := 0
309		for _, c := range b {
310			var d int
311			switch {
312			case '0' <= c && c <= '9':
313				d = int(c - '0')
314			case 'a' <= c && c <= 'f':
315				d = int(c-'a') + 10
316			case 'A' <= c && c <= 'F':
317				d = int(c-'A') + 10
318			default:
319				return 0, fmt.Errorf("invalid hex digit %q", c)
320			}
321			v = v*16 + d
322		}
323		return rune(v), nil
324	}
325	
326	// parseOneHeartbeat decodes one submit-input record and applies the
327	// submit-only rule that collection time cannot be later than receive time.
328	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
329		h, err := decodeStrictHeartbeatObject(raw)
330		if err != nil {
331			return Heartbeat{}, err
332		}
333		if h.CollectedAt.After(receiveTime) {
334			return Heartbeat{}, fmt.Errorf("collected_at %s is later than receive time %s",
335				h.CollectedAt.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
336		}
337		return h, nil
338	}
339	
340	func containsString(list []string, s string) bool {
341		for _, v := range list {
342			if v == s {
343				return true
344			}
345		}
346		return false
347	}
