271	func cmdHistory(args []string) {
272		fs := newFlagSet("heartbeat history")
273		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
274		node := fs.String("node", "", "node id (required)")
275		if err := fs.Parse(args); err != nil {
