277				os.Exit(0)
278			}
279			os.Exit(2)
280		}
281		if *node == "" {
282			die("--node is required")
283		}
284	
285		store, err := edgefleet.OpenStore(*dataDir)
286		if err != nil {
287			die("%v", err)
288		}
289		records, err := store.History(*node)
290		if err != nil {
291			die("%v", err)
292		}
293		if len(records) == 0 {
294			fmt.Printf("node=%s no heartbeats\n", *node)
295			return
296		}
297		for _, r := range records {
298			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
299				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
300		}
301	}
302	
303	func runDemo() {
304		nodes := []edgefleet.Node{
305			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
306			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
307			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
308		}
309		unhealthy := 0
310		for _, node := range nodes {
311			health := edgefleet.Evaluate(node, "1.26.0", 1)
312			if !health.Healthy {
313				unhealthy++
314			}
315			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
316		}
317		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
318		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
319	}
