33	const (
34		// cliTestEnv makes the re-executed test binary run the real main() instead
35		// of the test suite.
36		cliTestEnv = "EDGEFLEET_CLI_TEST_HELPER_PROCESS"
37	
38		// Fixed instants: heartbeats arrive and are queried at known times, so
39		// online status is deterministic without sleeping.
40		cliReceiveAt = "2026-10-01T12:00:00Z"
41		cliQueryAt   = "2026-10-01T12:00:00Z"
42	)
