50	func TestMain(m *testing.M) {
51		if os.Getenv(cliTestEnv) == "1" {
52			// Run the genuine command entry point and let its own os.Exit calls
53			// determine the helper process status.
54			main()
55			os.Exit(0)
56		}
57		os.Exit(m.Run())
58	}
