90	// submitBatch stores one JSON array via the real submit command.
91	func submitBatch(t *testing.T, dir, json string) {
92		t.Helper()
93		out, errOut, code := runCLI(t, dir, json,
94			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
95		if code != 0 {
