398	// validateRawNodeText checks the raw JSON string token of the node field
399	// before its decoded value is trusted. encoding/json silently rewrites
400	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
401	// would merge distinct node ids into one replacement-char id and break the
402	// ownership check against stored files. The raw token must decode
403	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
404	// escape must be a valid scalar value or a properly paired high/low
405	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
406	// user typed and is accepted; only undecodable input is rejected.
407	func validateRawNodeText(raw json.RawMessage) error {
408		raw = bytes.TrimSpace(raw)
409		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
410			return fmt.Errorf("node must be a string")
411		}
412		s := raw[1 : len(raw)-1]
413		for i := 0; i < len(s); {
414			c := s[i]
415			if c == '\\' {
416				if i+1 >= len(s) {
417					return fmt.Errorf("node contains a truncated escape")
418				}
419				if s[i+1] != 'u' {
420					i += 2
421					continue
422				}
423				if i+6 > len(s) {
424					return fmt.Errorf("node contains a truncated \\u escape")
425				}
426				r, err := parseHex4(s[i+2 : i+6])
427				if err != nil {
428					return fmt.Errorf("node contains an invalid \\u escape: %w", err)
429				}
430				switch {
431				case r >= 0xD800 && r <= 0xDBFF:
432					// A high surrogate is only valid when immediately followed
433					// by a low-surrogate \u escape.
434					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
435						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
436					}
437					lo, err := parseHex4(s[i+8 : i+12])
438					if err != nil {
439						return fmt.Errorf("node contains an invalid \\u escape: %w", err)
440					}
441					if lo < 0xDC00 || lo > 0xDFFF {
442						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
443					}
444					i += 12
445				case r >= 0xDC00 && r <= 0xDFFF:
446					return fmt.Errorf("node contains an unpaired low surrogate \\u%04X", r)
447				default:
448					i += 6
449				}
450				continue
451			}
452			if c < utf8.RuneSelf {
453				i++
454				continue
455			}
456			// A valid multi-byte rune decodes with size >= 2; size 1 means the
457			// bytes are not valid UTF-8 (including surrogate encodings).
458			_, size := utf8.DecodeRune(s[i:])
459			if size == 1 {
460				return fmt.Errorf("node contains invalid UTF-8 at byte offset %d", i)
461			}
462			i += size
463		}
464		return nil
465	}
