467	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
468	func parseHex4(b []byte) (rune, error) {
469		v := 0
470		for _, c := range b {
471			var d int
472			switch {
473			case '0' <= c && c <= '9':
474				d = int(c - '0')
475			case 'a' <= c && c <= 'f':
476				d = int(c-'a') + 10
477			case 'A' <= c && c <= 'F':
478				d = int(c-'A') + 10
479			default:
480				return 0, fmt.Errorf("invalid hex digit %q", c)
481			}
482			v = v*16 + d
483		}
484		return rune(v), nil
485	}
